import java.util.ArrayList;
import java.util.List;

public final class WordWrap {
    private WordWrap() {}

    /** Greedy word-wrap: pack words onto lines of at most `width` chars,
     *  single spaces between words on a line. A single word longer than
     *  width gets its own (overflowing) line - it is never split. */
    public static List<String> wrap(String text, int width) {
        List<String> lines = new ArrayList<>();
        if (text == null || text.isBlank()) {
            return lines;
        }
        StringBuilder line = new StringBuilder();
        for (String word : text.trim().split("\\s+")) {
            if (line.length() == 0) {
                line.append(word);
            } else if (line.length() + 1 + word.length() <= width) {
                line.append(' ').append(word);
            } else {
                lines.add(line.toString());
                line = new StringBuilder(word);
            }
        }
        if (line.length() > 0) {
            lines.add(line.toString());
        }
        return lines;
    }
}

