import java.util.List;

public final class WordWrapTest {
    public static void main(String[] args) {
        checkBasicWrap();
        checkExactWidthFit();
        checkBlankInput();
        System.out.println("all tests passed");
    }

    static void checkBasicWrap() {
        List<String> got = WordWrap.wrap("the quick brown fox jumps", 10);
        List<String> expected = List.of("the quick", "brown fox", "jumps");
        if (!got.equals(expected)) {
            throw new AssertionError("wrap(...) = " + got + ", expected " + expected);
        }
    }

    static void checkExactWidthFit() {
        // "ab cd" is exactly 5 chars - must stay on ONE line at width 5
        List<String> got = WordWrap.wrap("ab cd ef", 5);
        List<String> expected = List.of("ab cd", "ef");
        if (!got.equals(expected)) {
            throw new AssertionError("wrap(...) = " + got + ", expected " + expected
                    + " (a word exactly filling the width must not overflow)");
        }
    }

    static void checkBlankInput() {
        if (!WordWrap.wrap("", 10).isEmpty()) {
            throw new AssertionError("empty input must give an empty list");
        }
        if (!WordWrap.wrap("   ", 10).isEmpty()) {
            throw new AssertionError("blank input must give an empty list");
        }
    }
}

