import java.util.List;

public final class WordWrapTest {
    public static void main(String[] args) {
        List<String> got = WordWrap.wrap("hello world", 20);
        if (got.size() != 1) {
            throw new AssertionError("short text should fit on one line");
        }
        if (!WordWrap.wrap("", 10).isEmpty()) {
            throw new AssertionError("empty input must give an empty list");
        }
        List<String> longer = WordWrap.wrap("a b c d e f g h", 3);
        if (longer.isEmpty()) {
            throw new AssertionError("long text must produce some lines");
        }
        System.out.println("all tests passed");
    }
}
